import socket, concurrent.futures
ips=[f'172.22.0.{i}' for i in range(1,255)]
ports=[80,8080,3000,5000,8000,9000]
def chk(a):
    ip,p=a; s=socket.socket(); s.settimeout(0.5)
    try: s.connect((ip,p)); return (ip,p)
    except Exception: return None
    finally: s.close()
with concurrent.futures.ThreadPoolExecutor(200) as ex:
    for r in ex.map(chk, [(i,p) for i in ips for p in ports]):
        if r: print("OPEN", r)
EOF"}

